//! Shared helper for the Gate-G1 golden parity tests
//! (`tests/golden_*.rs`): pvlib-rust primitives vs pinned
//! pvlib-python 0.15.2 / ephem 4.2.1 fixtures.
//!
//! Fixtures + exact call chains / tolerances / deviations are documented in
//! `solar-engine/tools/py-golden/MANIFEST.json` and generated by
//! `solar-engine/tools/py-golden/generate.py` — that script is the source of
//! truth for every chain replicated below; if the two disagree, the script
//! wins and this file has a bug.
//!
//! Not a test target itself: it lives in a `tests/golden/` subdirectory, so
//! cargo doesn't compile it as its own test binary. Every `tests/golden_*.rs`
//! file pulls it in with `#[path = "golden/mod.rs"] mod golden;`.
//!
//! # Convention reconciliation (done once, here)
//!
//! - **Azimuth zero point**: pvlib-python's `solarposition.spa_python` and
//!   pvlib-rust's `solarposition::SolarPosition` both report azimuth in
//!   "degrees clockwise from North" (0=N, 90=E, 180=S, 270=W). pvlib-rust's
//!   `solarposition` module computes this via the `solar-positioning` crate's
//!   full NREL SPA (Reda & Andreas 2003/2004, replacing the earlier `spa`
//!   crate which was actually PSA/Blanco-Muriel — see
//!   `solar-engine/docs/decisions/spa-solar-position.md`), whose own
//!   documented coordinate system is "0 deg = North, clockwise" — the SAME
//!   zero point as pvlib. `golden_solarposition.rs` asserts this numerically
//!   (transit-time azimuth close to 180 for all 18 — all northern-hemisphere
//!   — locations) instead of just trusting the docstring. No sign flip or
//!   offset is applied anywhere in this file.
//! - **Zenith vs elevation**: `elevation = 90 - zenith` on both sides.
//! - **Pressure units**: pvlib's `alt2pres` / `spa_python` take/return
//!   Pascals; ephem's `Observer.pressure` is millibar/hPa (not used
//!   numerically here, only carried in fixture columns for reference).
//!   pvlib-rust's `atmospheric_refraction_correction` takes millibar
//!   (matching pvlib-python's `spa.py`, which divides its Pascal input by
//!   100 before applying the NREL refraction formula); the public
//!   `get_solarposition_apparent` wrapper takes Pascals and does that
//!   conversion internally, so this file always passes Pascals to it.
//! - **erbs() kt**: pvlib's `irradiance.erbs` returns `(dni, dhi, kt)`;
//!   pvlib-rust's `irradiance::erbs` returns only `(dni, dhi)` — `kt` isn't
//!   part of the public return value. `golden_decomposition.rs` recomputes
//!   the same clearness index pvlib-rust's `erbs()` computes internally
//!   (`cos_z` clamped to `min_cos_zenith=0.065`, matching pvlib-python's own
//!   `erbs()` default; this floor was previously a defect at `cos(85
//!   deg)=0.08716`, fixed alongside the SPA swap, see the decision doc above)
//!   `kt = ghi / (dni_extra * cos_z)`, unclamped above, to test "the kt
//!   implied by the primitive", rather than substituting the
//!   differently-clamped public `clearness_index()` function (which floors
//!   `cos_zenith` at 0.01 and clamps the result to [0, 1] — still a
//!   documented gap, not a bug, from `erbs()`'s own internal, unclamped kt).
//!   Both sides use the exact same `get_extra_radiation` (Spencer 1971, solar
//!   constant 1366.1).

#![allow(dead_code)]

use std::collections::HashMap;
use std::env;
use std::fs::File;
use std::path::{Path, PathBuf};

use chrono::{DateTime, Datelike, NaiveDateTime, TimeZone, Utc};
use flate2::read::GzDecoder;
use serde::Deserialize;

// ---------------------------------------------------------------------------
// Fixture directory / skip-if-unset
// ---------------------------------------------------------------------------

/// Reads `PVLIB_GOLDEN_DIR`. `None` means "fixtures not fetched" — every
/// golden test must skip cleanly (via `require_fixture_dir!`) rather than
/// fail, so `cargo test` stays green for anyone who hasn't pulled the
/// solar-engine fixtures.
pub fn fixture_dir() -> Option<PathBuf> {
    match env::var("PVLIB_GOLDEN_DIR") {
        Ok(v) if !v.trim().is_empty() => Some(PathBuf::from(v)),
        _ => None,
    }
}

/// `locations.json` lives next to `fixtures/` and `fixtures-full/` in
/// `tools/py-golden/`, so it's always the fixture dir's parent.
pub fn locations_json_path(fixture_dir: &Path) -> PathBuf {
    fixture_dir
        .parent()
        .expect("PVLIB_GOLDEN_DIR should be a fixtures/ or fixtures-full/ subdirectory of tools/py-golden/")
        .join("locations.json")
}

/// Every golden test starts with:
/// ```ignore
/// let Some(dir) = golden::fixture_dir() else {
///     eprintln!("SKIP: PVLIB_GOLDEN_DIR not set; skipping golden parity test.");
///     return;
/// };
/// ```
/// so `cargo test` stays green (with a visible SKIP note) for anyone who
/// hasn't fetched the solar-engine fixtures.
pub const SKIP_MESSAGE: &str = "SKIP: PVLIB_GOLDEN_DIR is not set; skipping Gate-G1 golden parity test. \
     Set it to solar-engine/tools/py-golden/fixtures (subset) or \
     .../fixtures-full (1-year grid) to run this test.";

// ---------------------------------------------------------------------------
// Location metadata (locations.json)
// ---------------------------------------------------------------------------

#[derive(Debug, Clone, Deserialize)]
pub struct LocationMeta {
    pub slug: String,
    #[allow(dead_code)]
    pub repo: String,
    pub lat: f64,
    pub lon: f64,
    pub alt: f64,
}

pub fn load_locations(fixture_dir: &Path) -> HashMap<String, LocationMeta> {
    let path = locations_json_path(fixture_dir);
    let data =
        std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("read {}: {}", path.display(), e));
    let list: Vec<LocationMeta> =
        serde_json::from_str(&data).unwrap_or_else(|e| panic!("parse {}: {}", path.display(), e));
    list.into_iter().map(|l| (l.slug.clone(), l)).collect()
}

// ---------------------------------------------------------------------------
// CSV.gz reading
// ---------------------------------------------------------------------------

/// Opens a gzipped fixture CSV for streaming row-by-row deserialization.
/// Streaming (rather than loading the whole file) matters on the 1-year
/// grid: clearsky/decomposition fixtures run to 2.5M rows.
pub fn open_csv_gz(dir: &Path, name: &str) -> csv::Reader<GzDecoder<File>> {
    let path = dir.join(name);
    let file = File::open(&path).unwrap_or_else(|e| panic!("open {}: {}", path.display(), e));
    csv::Reader::from_reader(GzDecoder::new(file))
}

// ---------------------------------------------------------------------------
// Timestamp parsing
// ---------------------------------------------------------------------------

/// Parses the fixtures' `timestamp_utc` columns, format
/// `%Y-%m-%dT%H:%M:%SZ` (always UTC).
pub fn parse_ts_z(s: &str) -> DateTime<Utc> {
    NaiveDateTime::parse_from_str(s, "%Y-%m-%dT%H:%M:%SZ")
        .unwrap_or_else(|e| panic!("bad timestamp {s:?}: {e}"))
        .and_utc()
}

/// `parse_ts_z`, converted to `chrono_tz::Tz` for pvlib-rust's
/// `solarposition` API (which takes `DateTime<Tz>`).
pub fn parse_ts_z_tz(s: &str) -> DateTime<chrono_tz::Tz> {
    Utc.from_utc_datetime(&parse_ts_z(s).naive_utc())
        .with_timezone(&chrono_tz::UTC)
}

/// Parses the sunrise/sunset fixture's full ISO-8601 (`isoformat()`)
/// timestamps, e.g. `2025-01-04T06:17:19.153088+00:00`.
pub fn parse_rfc3339_utc(s: &str) -> DateTime<Utc> {
    DateTime::parse_from_rfc3339(s)
        .unwrap_or_else(|e| panic!("bad rfc3339 timestamp {s:?}: {e}"))
        .with_timezone(&Utc)
}

/// pandas/pvlib `dayofyear` (1-based) for a given UTC instant.
pub fn day_of_year(ts: DateTime<Utc>) -> u32 {
    ts.ordinal()
}

// ---------------------------------------------------------------------------
// Tolerance rules (docs/PLAN.md Etapa 1 / MANIFEST.json tolerances_G1)
// ---------------------------------------------------------------------------

/// Solar position tolerance: 0.01 degrees, full day.
pub const POSITION_TOL_DEG: f64 = 0.01;

/// Sunrise/sunset "+/- one 15-min slot" rule (refraction: ephem vs SPA).
pub const SUNRISE_SUNSET_TOL_SECONDS: f64 = 900.0;

/// Power tolerance: 0.1% relative (1e-6 W absolute floor for exact zeros).
pub const POWER_REL_TOL: f64 = 0.001;
pub const POWER_ABS_FLOOR: f64 = 1e-6;

/// Irradiance tolerance: <= 1 W/m^2 absolute OR 0.5% relative, whichever is
/// larger. Per the task spec this same numeric rule is also applied to the
/// (degree-valued) `aoi` column in the transposition test.
pub fn irradiance_tol(want: f64) -> f64 {
    1.0_f64.max(0.005 * want.abs())
}

pub fn power_tol(want: f64) -> f64 {
    (POWER_REL_TOL * want.abs()).max(POWER_ABS_FLOOR)
}

/// Smallest angle between two azimuths in degrees, handling 0/360 wraparound.
pub fn azimuth_diff(a: f64, b: f64) -> f64 {
    let d = (a - b).abs() % 360.0;
    d.min(360.0 - d)
}

// ---------------------------------------------------------------------------
// Error accumulation + reporting ("max/p99 per column per location", "10
// worst rows on failure")
// ---------------------------------------------------------------------------

#[derive(Default)]
pub struct ErrorTracker {
    errors: Vec<f64>,
    /// Bounded top-10, kept sorted ascending by error so `worst[0]` is the
    /// smallest of the ten currently held (the eviction candidate).
    worst: Vec<(f64, String)>,
}

impl ErrorTracker {
    fn new() -> Self {
        Self::default()
    }

    pub fn record(&mut self, err: f64, describe: impl FnOnce() -> String) {
        self.errors.push(err);
        if self.worst.len() < 10 {
            self.worst.push((err, describe()));
            self.worst.sort_by(|a, b| a.0.partial_cmp(&b.0).unwrap());
        } else if err > self.worst[0].0 {
            self.worst[0] = (err, describe());
            self.worst.sort_by(|a, b| a.0.partial_cmp(&b.0).unwrap());
        }
    }

    pub fn len(&self) -> usize {
        self.errors.len()
    }

    pub fn max(&self) -> f64 {
        self.errors.iter().cloned().fold(0.0, f64::max)
    }

    /// Nearest-rank p99 (not interpolated — fine for the sample sizes here).
    pub fn p99(&self) -> f64 {
        if self.errors.is_empty() {
            return 0.0;
        }
        let mut sorted = self.errors.clone();
        sorted.sort_by(|a, b| a.partial_cmp(b).unwrap());
        let idx = ((sorted.len() as f64) * 0.99).ceil() as usize;
        let idx = idx.min(sorted.len()).saturating_sub(1);
        sorted[idx]
    }
}

/// Per-(location, column) (or any other string key) error trackers, printed
/// as one report block. This is the "accumulate and print max/p99 error per
/// column per location; on failure print the 10 worst rows" mechanism used
/// by every golden test.
#[derive(Default)]
pub struct TrackerSet {
    by_key: HashMap<String, ErrorTracker>,
}

impl TrackerSet {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn record(&mut self, key: &str, err: f64, describe: impl FnOnce() -> String) {
        self.by_key
            .entry(key.to_string())
            .or_insert_with(ErrorTracker::new)
            .record(err, describe);
    }

    pub fn is_empty(&self) -> bool {
        self.by_key.is_empty()
    }

    pub fn global_max(&self) -> f64 {
        self.by_key.values().map(|t| t.max()).fold(0.0, f64::max)
    }

    /// Prints one line per key (sorted, for stable output) plus the 10
    /// globally-worst rows across all keys. Always call this (pass or fail)
    /// with `cargo test -- --nocapture` to get the full G1 evidence dump.
    pub fn report(&self, title: &str) {
        eprintln!("--- {title} ---");
        if self.by_key.is_empty() {
            eprintln!("  (no rows)");
            return;
        }
        let mut keys: Vec<&String> = self.by_key.keys().collect();
        keys.sort();
        for k in keys {
            let t = &self.by_key[k];
            eprintln!(
                "  {k:<40} n={:>8} max={:>12.6} p99={:>12.6}",
                t.len(),
                t.max(),
                t.p99()
            );
        }
        let mut all_worst: Vec<(f64, String)> = self
            .by_key
            .values()
            .flat_map(|t| t.worst.iter().cloned())
            .collect();
        all_worst.sort_by(|a, b| b.0.partial_cmp(&a.0).unwrap());
        all_worst.truncate(10);
        if !all_worst.is_empty() {
            eprintln!("  worst offenders overall (up to 10):");
            for (err, desc) in &all_worst {
                eprintln!("    err={err:.6}  {desc}");
            }
        }
    }
}

