fn de_opt_f64<'de, D>(d: D) -> Result<Option<f64>, D::Error>
where
    D: serde::Deserializer<'de>,
{
    let s = String::deserialize(d)?;
    let s = s.trim();
    if s.is_empty() {
        Ok(None)
    } else {
        s.parse::<f64>().map(Some).map_err(serde::de::Error::custom)
    }
}

#[derive(Debug, Clone, Deserialize)]
pub struct DecompositionRow {
    pub slug: String,
    pub timestamp_utc: String,
    pub cloud_factor: f64,
    pub ghi: f64,
    pub kt: f64,
    pub dni_erbs: f64,
    pub dhi_erbs: f64,
    #[serde(deserialize_with = "de_opt_f64")]
    pub dni_dirint: Option<f64>,
}

/// Minimal solar-angle join target (`decomposition.csv.gz` and
/// `transposition_isotropic.csv.gz` don't carry their own solar angles —
/// they're joined from `solarposition.csv.gz` by `(slug, timestamp_utc)`,
/// exactly as `generate.py` computes them from the same `sp` DataFrame).
#[derive(Debug, Clone, Copy)]
pub struct SolarAngles {
    pub zenith: f64,
    pub apparent_zenith: f64,
    pub azimuth: f64,
}

fn join_key(slug: &str, timestamp_utc: &str) -> String {
    let mut k = String::with_capacity(slug.len() + 1 + timestamp_utc.len());
    k.push_str(slug);
    k.push('|');
    k.push_str(timestamp_utc);
    k
}

/// Builds the `(slug, timestamp_utc) -> SolarAngles` join map from
/// `solarposition.csv.gz`, for tests that need SPA zenith/azimuth as an
/// input but whose own fixture file doesn't carry those columns.
pub fn load_solar_angles(dir: &Path) -> HashMap<String, SolarAngles> {
    let mut map = HashMap::new();
    let mut rdr = open_csv_gz(dir, "solarposition.csv.gz");
    for rec in rdr.deserialize::<SolarPositionRow>() {
        let row = rec.expect("solarposition.csv.gz row");
        map.insert(
            join_key(&row.slug, &row.timestamp_utc),
            SolarAngles {
                zenith: row.zenith,
                apparent_zenith: row.apparent_zenith,
                azimuth: row.azimuth,
            },
        );
    }
    map
}

pub fn lookup_angles<'a>(
    map: &'a HashMap<String, SolarAngles>,
    slug: &str,
    timestamp_utc: &str,
) -> &'a SolarAngles {
    map.get(&join_key(slug, timestamp_utc))
        .unwrap_or_else(|| panic!("no solarposition join row for slug={slug} ts={timestamp_utc}"))
}
